"""Concise rules for single-principle retained operations, never teaching prose."""
RULES={
'number_classifications_properties':'Check the defining property: square and cube numbers are integer powers, primes have exactly two positive divisors, and a rational number is a ratio of integers.',
'directed_numbers_in_action':'Represent each stated increase by a positive change and each decrease by a negative change; subtract in the requested comparison order.',
'fractions_decimals_percentages':'A fraction represents numerator divided by denominator; a percentage is that ratio multiplied by 100. Preserve the value in each conversion.',
'standard_form_estimates_approximations':'Moving the decimal point one place changes its power-of-ten exponent by one in the opposite direction; the standard-form coefficient is at least 1 and below 10.',
'defining_sets_notation':'Membership requires the element to satisfy the complete stated condition; exclude every element that fails it.',
'metric_units_conversions':'Multiply by the unit ratio in the required direction; square that ratio for area and cube it for volume.',
'perimeters_areas_polygons':'Perimeter adds boundary lengths; area multiplies a base by its perpendicular height, with a half factor for a triangle.',
'circles_arcs_sectors':'Use A=πr² for area or C=2πr for circumference, halving a supplied diameter first.',
'surface_area_volume':'A prism volume is base area times perpendicular height; surface area instead adds the exposed face areas.',
'similarity_scale_factors':'Corresponding lengths have the same linear scale factor; obtain it from corresponding sides in the requested direction.',
'angles_lines_polygons':'Use 180° on a straight line or in a triangle, 360° around a point, and (n−2)180° for an n-gon interior sum; equal-angle properties determine how that total is shared.',
'angles_circles':'Use the theorem matching the stated configuration: centre angles double circumference angles on the same arc, opposite cyclic angles sum to 180°, and a radius is perpendicular to its tangent.',
'algebraic_manipulation_expansion':'Distribute each multiplier to every term, retaining the signs, then collect only like powers of the same variable.',
'factorisation_basics':'Extract the greatest common numerical and variable factors; divide every original term by the extracted factor.',
'inequalities_indices':'Equal bases allow comparison of exponents; multiplication adds exponents, division subtracts them, and an outside power multiplies them.',
'functions':'Substitute the complete signed input for every occurrence of the variable and evaluate powers before multiplication and addition.',
'straight_line_graphs_gradients':'In y=mx+c, m is the gradient and c the y-intercept; a point on the line satisfies the entire equation.',
'distance_midpoint_gradient':'A midpoint averages corresponding endpoint coordinates; use both endpoints once in each coordinate.',
'parallel_perpendicular_quadrilaterals':'Equal directed side displacements establish parallel equal sides; nonvertical perpendicular gradients have product −1.',
'vector_operations_magnitude':'Addition operates component by component; magnitude is the positive square root of the sum of component squares.',
'matrix_basics':'Add or subtract entries in matching row-column positions; a scalar multiplies every entry. Preserve the matrix dimensions.',
'bearings_right_angled_triangles':'Choose sine, cosine or tangent by the known and requested sides relative to the stated angle; bearings are measured clockwise from north.',
'sine_cosine_rules':'Triangle area is half the product of two sides and the sine of their included angle; a right-triangle diagonal follows from Pythagoras.',
'cumulative_frequency_reading':'A cumulative count includes all observations up to the boundary; subtract endpoint totals for an interval and use count/total for its proportion.',
'simple_probability':'For equally likely outcomes divide favourable count by total count; expected frequency is probability multiplied by trial count.',
'tree_diagrams':'Multiply conditional probabilities along a path and add disjoint qualifying paths; a complementary event has probability one minus the original event.',
'histograms_text':'Frequency equals class width multiplied by frequency density, so class width must be retained even when heights match.',
'reading_charts_text':'Read the category value on the labelled scale, then apply the requested sum or difference without treating tick positions as frequencies.',
'prepared_line_graphs':'Read across from the requested coordinate to the line and then to the other labelled axis, using its scale and units.',
}
TASKS={
('number_classifications_properties','classify_number'):'Simplify the complete expression first; a rational result can be written as a ratio of integers, whereas an irrational result cannot.',
('vector_operations_magnitude','magnitude'):'A vector’s magnitude follows from Pythagoras: square each signed component, add the nonnegative squares, then take the nonnegative square root.',
('simple_probability','expected_frequency'):'Expected frequency is the event probability multiplied by the number of trials; it is an expectation rather than a guaranteed count.',
}

def operation_reason(family,task):
    if (family,task) in TASKS:return TASKS[(family,task)]
    if family not in RULES:raise ValueError(f'Missing operation rule: {family}/{task}')
    return RULES[family]

# These task rules take precedence over the family relationship. Each states
# the principle actually used by that branch, rather than a list of alternatives.
TASK_RULES={
'difference_of_squares':'Recognise a²−b² and factor it as (a−b)(a+b); the cross terms cancel on expansion.',
'common_number_factor':'Extract the greatest common numerical divisor, dividing every term by it.',
'common_letter_factor':'Extract the shared numerical factor and the lowest shared power of each variable.',
'cuboid_volume':'Multiply the three perpendicular edge lengths to count cubic units.',
'cuboid_area':'Add the areas of all six faces: two of each pair of perpendicular dimensions.',
'cylinder_volume':'Multiply circular base area πr² by perpendicular height.',
'cylinder':'Unwrap the curved surface to a rectangle with circumference 2πr as its width and cylinder height as its other dimension.',
'sphere':'Use V=4πr³/3, cubing the radius rather than the diameter.',
'hemisphere':'A hemisphere is half a sphere, so halve the full sphere volume without halving its radius.',
'cone':'Cone volume is one third of circular base area multiplied by perpendicular height, not slant height.',
'pyramid':'Find the square base area first, then multiply by perpendicular height and divide by three.',
'cone_slant':'Cone curved area is π times radius times slant height; it excludes the circular base.',

'pick_from_list':'Test each candidate against the requested number property and select the matching entry.',
'primes_in_range':'Check divisibility by primes up to each candidate’s square root; retain exactly the primes in the stated inclusive range.',
'compare_negatives':'On the number line the value farther to the right is greater, including when both values are negative.',
'balance_and_position':'Add signed credits and debits in their stated order; a negative closing balance represents money owed.',
'expense':'Subtract the outgoing amount from the available balance.',
'temperature_after_change':'Add a rise and subtract a fall from the initial signed temperature.',
'temperature_change':'Subtract the initial temperature from the final temperature; the sign states the direction of change.',
'decimal_to_fraction':'Use a denominator of 10 raised to the number of decimal places, then cancel the numerator and denominator by their common factor.',
'percentage_to_fraction':'Divide the percentage by 100 and reduce the resulting fraction.',
'fraction_to_decimal':'Divide numerator by denominator, retaining the required precision.',
'fraction_to_percentage':'Multiply the fraction by 100 to express it per hundred.',
'equivalent_fraction':'Multiply numerator and denominator by the same factor so the value remains unchanged.',
'fraction_of_quantity':'Divide the whole by the denominator and multiply by the numerator.',
'improper_to_mixed':'Divide numerator by denominator; the quotient gives whole units and the remainder is the numerator over the original denominator.',
'recurring_to_fraction':'Multiply by the period’s power of ten and subtract the original decimal so the recurring tails cancel; isolate the original value.',
'fraction_mul':'Multiply numerators together and denominators together, then cancel common factors.',
'from_standard_form':'Multiply the coefficient by the stated power of ten to restore the ordinary number.',
'to_standard_form':'Move the decimal point until the coefficient is at least 1 and below 10, compensating with the exponent on ten.',
'list_factors':'Keep exactly the positive integers that divide the supplied number without remainder.',
'list_multiples':'Generate integer multiples of the supplied number and retain those inside the stated bounds.',
'list_primes':'Keep numbers greater than 1 with exactly two positive divisors, respecting the given bounds.',
'list_squares':'Square the permitted integer roots and retain values meeting the stated bounds.',
'notation':'Use membership for elements, subset notation for sets, and the universal set when interpreting complements.',
'convert':'Multiply by the ratio of the source unit to the requested unit.',
'convert_area_volume':'Raise the length conversion factor to the second power for area or third power for volume.',
'rect_area':'Rectangle area is length multiplied by perpendicular width.',
'rect_perimeter':'A rectangle has two sides of each length, so its perimeter is twice length plus twice width.',
'triangle_area':'Triangle area is half base multiplied by perpendicular height.',
'parallelogram_area':'Area is base multiplied by perpendicular height, not the slanted side.',
'area':'Circle area is π times radius squared.',
'circumference':'Circumference is 2π times radius, using half the diameter when a diameter is given.',
'similar_lengths':'Corresponding lengths in similar shapes have one common scale factor.',
'straight_line':'Adjacent angles on a straight line sum to 180°.',
'point':'Angles making a complete turn about one point sum to 360°.',
'crossing_opposite':'Vertically opposite angles formed by intersecting straight lines are equal.',
'crossing_adjacent':'Adjacent angles at a straight-line intersection sum to 180°.',
'exterior':'A triangle exterior angle equals the sum of its two opposite interior angles.',
'isosceles_apex':'Subtract the apex angle from 180° and divide the remaining sum equally between the two equal base angles.',
'isosceles_base':'An isosceles triangle has two equal base angles; subtract both from 180° to find the apex.',
'parallel_lines':'Use the corresponding or alternate equal-angle pair, or the co-interior supplementary pair, named by the rays in the question.',
'sides_from_exterior':'Equal exterior angles of a regular polygon add to 360°; divide that total by one exterior angle.',
'sum_interior':'An n-gon can be divided into n−2 triangles, giving an interior sum of (n−2)180°.',
'interior_regular':'Divide the polygon interior sum (n−2)180° equally among its n angles.',
'unknown_angle':'Subtract the known angles from the polygon interior sum, then divide the remainder among the specified equal unknown angles.',
'at_centre':'The angle at the centre is twice the angle at the circumference standing on the same arc.',
'at_circumference':'The angle at the circumference is half the central angle on the same arc.',
'same_segment':'Angles at the circumference standing on the same chord and in the same segment are equal.',
'semicircle':'The angle subtended by a diameter at the circumference is 90°.',
'tangent_triangle':'A radius is perpendicular to its tangent; subtract that right angle and the other given angle from 180°.',
 'tangent_chord_radius':'The alternate-segment theorem gives the tangent-chord angle; subtract it from the radius-tangent right angle.',
 'tangent_pair_aob':'The two radii meet the tangents at right angles; subtract those two right angles and the exterior angle from the quadrilateral total 360°.',
 'tangent_pair_pab':'Tangents from the same external point have equal lengths, so their two base angles share 180° minus the angle between the tangents.',
 'alt_segment_acb':'The angle between a tangent and a chord equals the angle in the alternate segment.',
 'alt_segment_oab':'Subtract the alternate-segment angle from the 90° radius-tangent angle.',
 'alt_segment_aob':'Combine the alternate-segment angle with the centre-angle theorem: the central angle on the arc is twice the circumference angle.',
 'cyclic_adc':'Opposite interior angles of a cyclic quadrilateral sum to 180°.',
'cyclic_bcd':'Opposite interior angles of a cyclic quadrilateral sum to 180°.',
'reflex':'Double the circumference angle standing on the same arc to find the requested reflex central angle.',
'radii_isosceles':'Equal radii form an isosceles triangle; its two base angles share 180° minus the central angle.',
'evaluate_negative':'A negative exponent denotes the reciprocal of the corresponding positive power.',
'index_multiply':'Multiplication of powers with the same base adds their exponents.',
'index_divide':'Division of powers with the same nonzero base subtracts the denominator exponent.',
'index_power':'Raising a power to another power multiplies the exponents.',
'power_of_product':'An outside power applies to every factor of a product.',
'product_of_terms':'Multiply numerical coefficients and add exponents of each matching variable.',
'divide_terms':'Divide numerical coefficients and subtract exponents of matching variables.',
'single_power':'Express all factors using the requested common base and combine their exponents.',
'numeric_index':'Evaluate powers before multiplication and division; a negative exponent takes a reciprocal.',
'gradient_from_equation':'In y=mx+c the coefficient m gives the gradient.',
'intercept_from_equation':'At the y-intercept x=0, so the constant c gives its ordinate.',
'point_on_line_value':'Substitute the known coordinate into the full line equation to recover the other coordinate.',
'midpoint':'Average the two x-coordinates and separately average the two y-coordinates.',
'midpoint_fraction':'A midpoint is half the sum of corresponding coordinates; retain exact fractional values.',
'find_other_end':'Twice each midpoint coordinate equals the sum of the endpoint coordinates; subtract the known endpoint.',
'parallel_perpendicular_gradient':'Parallel nonvertical lines have equal gradients; perpendicular nonvertical gradients multiply to −1.',
'parallelogram_fourth_vertex':'Opposite directed sides of a parallelogram have equal displacements, so add the known side displacement to the opposite starting vertex.',
'vector_add':'Add corresponding signed components in the two vectors.',
'vector_subtract':'Subtract each second-vector component from the corresponding first-vector component.',
'vector_scalar':'Multiply every component by the scalar, reversing direction when it is negative.',
'parallelogram_vector':'The two sides from one vertex add to the displacement to the opposite vertex.',
'magnitude':'Square both signed components, add the squares, and take the nonnegative square root.',
'add':'Add matrix entries in matching row and column positions.',
'subtract':'Subtract each second matrix entry from the matching first matrix entry.',
'scalar':'Multiply every matrix entry by the stated scalar.',
'combination':'Multiply all entries by their stated scalar before adding or subtracting corresponding entries.',
'stock_total':'Add each stock entry exactly once, including every shop and item category.',
'stock_left':'Subtract sales from initial stock in the corresponding shop-item entry.',
'back_bearing':'Reverse direction by 180° and reduce to the interval from 000° up to 360°.',
'bearing_turn':'Add a clockwise turn or subtract an anticlockwise turn, wrapping the result into a full turn.',
'pythagoras':'In a right triangle the hypotenuse square equals the sum of the leg squares; take the positive square root for a length.',
'area_exact':'Triangle area is half the product of two sides and sine of their included angle; retain exact values.',
'pyramid_diagonal':'The base diagonal is the hypotenuse of the right triangle formed by the two perpendicular base edges.',
'frequencies_from_cumulative':'Subtract each preceding cumulative total to recover the count in the next class.',
'less_than':'The cumulative total at the boundary counts observations below that boundary.',
'at_least':'Subtract the count below the boundary from the overall observation count.',
'between':'Subtract the cumulative count at the lower boundary from the count at the upper boundary.',
'iqr':'Subtract the lower quartile reading from the upper quartile reading on the measurement scale.',
'expected':'Expected frequency is the event probability multiplied by the number of trials.',
'impossible':'An impossible event has no favourable outcomes and therefore probability zero.',
'missing_probability':'The probabilities of all disjoint exhaustive outcomes sum to one.',
'not':'The probability of the complementary event is one minus the event probability.',
'not_event':'Count all outcomes outside the specified event, relative to the whole sample space.',
'gradient_from_graph':'Choose two well-separated points on the line and divide their signed vertical change by their signed horizontal change.',
}
_base_reason=operation_reason

def operation_reason(family,task):
    # Disambiguate shared task names before applying the task dictionary.
    if family=='sine_cosine_rules' and task=='area':return 'Triangle area is half the product of two given sides and sine of their included angle.'
    return TASKS.get((family,task),TASK_RULES.get(task)) or _base_reason(family,task)
